contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, string calldata description) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(caller != address(this), "caller must not be the test contract");
        require(address(this).balance >= 0);

        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }

    receive() external payable {}
}

